 1	/* ============================================================
 2	   views/config.js — Configuration view
 3	   Section 4d of the MCP Server Dashboard SPA
 4	   Depends on: API, UI, escapeHtml, showLoading, showError
 5	   ============================================================ */
 6	
 7	/* ── Module-level state ──────────────────────────────────── */
 8	
 9	var configActiveTab = 'general';
10	
11	/* Dirty-tracking: keyed by tab name, true when the tab has unsaved changes */
12	var configDirty = {
13	  general: false,
14	  personaModels: false,
15	  modelRegistry: false
16	};
17	
18	/* ── Entry point ─────────────────────────────────────────── */
19	
20	function renderConfig(app) {
21	  showLoading(app);
22	
23	  Promise.all([
24	    API.getConfig(),
25	    API.getModels ? API.getModels() : Promise.resolve([]),
26	    API.getPersonas ? API.getPersonas() : Promise.resolve([]),
27	    API.getAssignments ? API.getAssignments() : Promise.resolve([])
28	  ]).then(function (results) {
29	    var config      = results[0];
30	    var models      = results[1];
31	    var personas    = results[2];
32	    var assignments = results[3];
33	
34	    renderConfigPage(app, config, models, personas, assignments);
35	  }).catch(function (err) {
36	    showError(app, 'Failed to load configuration: ' + (err.message || String(err)));
37	  });
38	}
39	
40	/* ── Page scaffold ───────────────────────────────────────── */
41	
42	function renderConfigPage(app, config, models, personas, assignments) {
43	  /* Reset dirty flags — fresh server data has just been loaded, so any stale
44	     dirty state from a previous page visit is no longer meaningful. */
45	  configDirty.general       = false;
46	  configDirty.personaModels = false;
47	  configDirty.modelRegistry = false;
48	
49	  /* Reset Model Registry local state so it re-initialises from fresh server data. */
50	  mrModels    = null;
51	  mrOriginal  = null;
52	  mrEditingId = null;
53	
54	  app.innerHTML =
55	    '<div class="page-header"><h1>Configuration</h1></div>' +
56	    '<div class="config-tabs" id="config-tab-bar">' +
57	      '<button class="config-tab' + (configActiveTab === 'general'       ? ' active' : '') + '" data-tab="general">General</button>' +
58	      '<button class="config-tab' + (configActiveTab === 'personaModels' ? ' active' : '') + '" data-tab="personaModels">Persona Models</button>' +
59	      '<button class="config-tab' + (configActiveTab === 'modelRegistry' ? ' active' : '') + '" data-tab="modelRegistry">Model Registry</button>' +
60	    '</div>' +
61	    '<div id="config-tab-content"></div>';
62	
63	  /* Render active tab content */
64	  renderConfigTabContent(config, models, personas, assignments);
65	
66	  /* Wire tab-bar clicks */
67	  var tabBar = document.getElementById('config-tab-bar');
68	  if (tabBar) {
69	    tabBar.addEventListener('click', function (e) {
70	      var btn = e.target.closest('button[data-tab]');
71	      if (!btn) return;
72	      var tab = btn.getAttribute('data-tab');
73	      if (tab === configActiveTab) return;
74	
75	      /* Unsaved-changes guard */
76	      if (configDirty[configActiveTab]) {
77	        if (!confirm('You have unsaved changes. Discard them?')) {
78	          return; /* Stay */
79	        }
80	        configDirty[configActiveTab] = false;

 81	        /* Reset Model Registry local state when discarding changes so a
 82	           fresh load occurs on the next visit. */
 83	        if (configActiveTab === 'modelRegistry') {
 84	          mrModels    = null;
 85	          mrOriginal  = null;
 86	          mrEditingId = null;
 87	        }
 88	      }
 89	
 90	      /* Update active tab state */
 91	      configActiveTab = tab;
 92	
 93	      /* Update active class on buttons without re-rendering the full page */
 94	      var allBtns = tabBar.querySelectorAll('.config-tab');
 95	      allBtns.forEach(function (b) {
 96	        b.classList.toggle('active', b.getAttribute('data-tab') === tab);
 97	      });
 98	
 99	      /* Re-render only the tab content area */
100	      renderConfigTabContent(config, models, personas, assignments);
101	    });
102	  }
103	}
104	
105	/* ── Tab content dispatcher ──────────────────────────────── */
106	
107	function renderConfigTabContent(config, models, personas, assignments) {
108	  var contentEl = document.getElementById('config-tab-content');
109	  if (!contentEl) return;
110	
111	  if (configActiveTab === 'general') {
112	    contentEl.innerHTML = renderGeneralTab(config);
113	    wireGeneralTabEvents();
114	  } else if (configActiveTab === 'personaModels') {
115	    contentEl.innerHTML = renderPersonaModelsTab(models, personas, assignments);
116	  } else if (configActiveTab === 'modelRegistry') {
117	    contentEl.innerHTML = renderModelRegistryTab(models);
118	    mrWireEvents();
119	  }
120	}
121	
122	/* ── General tab ─────────────────────────────────────────── */
123	
124	function renderGeneralTab(config) {
125	  return UI.card(null,
126	    '<form id="config-form">' +
127	      '<div class="form-group">' +
128	        '<label class="form-label" for="auto-handoff">' +
129	          '<input type="checkbox" id="auto-handoff" class="form-check" ' + (config.auto_handoff_enabled ? 'checked' : '') + '>' +
130	          ' Auto-handoff enabled' +
131	        '</label>' +
132	        '<p class="form-note">When enabled, the MCP server automatically chains work to the next agent in the workflow.</p>' +
133	      '</div>' +
134	      '<div class="form-group">' +
135	        '<label class="form-label" for="max-depth">Max handoff depth</label>' +
136	        '<input type="number" id="max-depth" class="form-control" min="1" value="' + escapeHtml(String(config.max_handoff_depth)) + '">' +
137	        '<p class="form-note">Maximum number of automatic agent handoffs before stopping.</p>' +
138	      '</div>' +
139	      '<div class="form-group">' +
140	        '<label class="form-label" for="capture-dialogues">' +
141	          '<input type="checkbox" id="capture-dialogues" class="form-check" ' + (config.capture_dialogues ? 'checked' : '') + '>' +
142	          ' Capture agent dialogues' +
143	        '</label>' +
144	        '<p class="form-note">When enabled, the orchestrator saves the full LLM conversation for each pipeline stage to the project\'s ledger as Markdown files. Changes take effect on the next orchestrator run.</p>' +
145	      '</div>' +
146	      '<div class="form-group">' +
147	        '<label class="form-label" for="auto-archive-days">Auto-archive after (days)</label>' +
148	        '<input type="number" id="auto-archive-days" class="form-control" min="0" step="1" value="' + escapeHtml(String(config.auto_archive_days != null ? config.auto_archive_days : 6)) + '">' +
149	        '<p class="form-note">Number of days after last update before a COMPLETE project is automatically archived. Set to 0 to disable auto-archiving.</p>' +
150	      '</div>' +
151	      '<div class="form-group">' +
152	        '<label class="form-label" for="ledger-root">Ledger root path</label>' +
153	        '<input type="text" id="ledger-root" class="form-control" readonly value="' + escapeHtml(config.ledger_root || '') + '">' +
154	        '<p class="form-note">Read-only. Changing this requires restarting the server with <code>--ledger-dir</code>.</p>' +
155	      '</div>' +
156	      '<button type="submit" class="btn btn-primary">Save</button>' +
157	      '<div id="config-msg"></div>' +
158	    '</form>',
159	    { style: 'max-width:560px' }
160	  );
161	}
162	
163	function wireGeneralTabEvents() {
164	  var form = document.getElementById('config-form');
165	  if (!form) return;
166	
167	  /* Mark tab dirty on any input change.
168	     Both 'change' and 'input' are intentional: checkboxes fire 'change'
169	     (not 'input'), while text/number inputs fire 'input' on each keystroke.
170	     Using both ensures all form control types are covered. */
171	  form.addEventListener('change', function () {
172	    configDirty.general = true;
173	  });
174	  form.addEventListener('input', function () {
175	    configDirty.general = true;
176	  });
177	
178	  form.addEventListener('submit', function (e) {
179	    e.preventDefault();
180	    var autoHandoff = document.getElementById('auto-handoff').checked;
181	    var maxDepth = parseInt(document.getElementById('max-depth').value, 10);
182	    if (isNaN(maxDepth) || maxDepth < 1) {
183	      showError(document.getElementById('config-msg'), 'Max handoff depth must be a positive integer.');
184	      return;
185	    }
186	    var captureDialogues = document.getElementById('capture-dialogues').checked;
187	    var autoArchiveDays = parseInt(document.getElementById('auto-archive-days').value, 10);
188	    if (isNaN(autoArchiveDays) || autoArchiveDays < 0) {
189	      showError(document.getElementById('config-msg'), 'Auto-archive days must be a non-negative integer.');
190	      return;
191	    }
192	    /* ledger_root intentionally omitted (read-only) */
193	    API.updateConfig({ auto_handoff_enabled: autoHandoff, max_handoff_depth: maxDepth, capture_dialogues: captureDialogues, auto_archive_days: autoArchiveDays })
194	      .then(function () {
195	        configDirty.general = false;
196	        document.getElementById('config-msg').innerHTML = '<p class="success-banner">Configuration saved.</p>';
197	      })
198	      .catch(function (err) {
199	        showError(document.getElementById('config-msg'), 'Save failed: ' + (err.message || String(err)));
200	      });
201	  });
202	}
203	
204	/* ── Persona Models tab (stub) ───────────────────────────── */
205	
206	function renderPersonaModelsTab(models, personas, assignments) {
207	  return UI.card(null,
208	    '<div class="empty-state">' +
209	      '<p class="empty-state-text">Persona Models — Coming soon</p>' +
210	      '<p class="form-note">Per-persona model assignment will be available in a future release.</p>' +
211	    '</div>',
212	    { style: 'max-width:560px' }
213	  );
214	}
215	
216	/* ── Model Registry tab ──────────────────────────────────── */
217	
218	/* Module-level state for Model Registry tab.
219	   mrModels:    working copy of the model list (may have edits / pending deletions).
220	   mrOriginal:  snapshot loaded from the server — used for dirty comparison.
221	   mrEditingId: id of the row currently in edit mode (null when none). */
222	var mrModels    = null;
223	var mrOriginal  = null;
224	var mrEditingId = null;
225	
226	/* Slug validation regex — mirrors the server-side rule. */
227	var MR_SLUG_REGEX = /^[a-z0-9]+(-[a-z0-9]+)*$/;
228	
229	/* ── Helpers ─────────────────────────────────────────────── */
230

231	/** Derive a slug from a human-readable name. */
232	function mrDeriveSlug(name) {
233	  return (name || '')
234	    .toLowerCase()
235	    .replace(/\s+/g, '-')
236	    .replace(/[^a-z0-9-]/g, '')
237	    .replace(/-+/g, '-')
238	    .replace(/^-|-$/g, '');
239	}
240	
241	/** Validate a slug string.  Returns an error message or '' if valid. */
242	function mrValidateSlug(slug) {
243	  if (!slug) return 'Slug is required.';
244	  if (slug === 'inherit') return 'The slug "inherit" is reserved.';
245	  if (!MR_SLUG_REGEX.test(slug)) return 'Slug must be lowercase alphanumeric with hyphens (e.g. my-model).';
246	  return '';
247	}
248	
249	/** Deep-clone a models array so mutations do not affect the original snapshot. */
250	function mrCloneModels(arr) {
251	  return arr.map(function (m) { return Object.assign({}, m); });
252	}
253	
254	/** Return true when the working copy has any unsaved changes vs the snapshot. */
255	function mrHasChanges() {
256	  if (!mrModels || !mrOriginal) return false;
257	  if (mrModels.length !== mrOriginal.length) return true;
258	  for (var i = 0; i < mrModels.length; i++) {
259	    var a = mrModels[i];
260	    var b = mrOriginal[i];
261	    if (a.id !== b.id || a.name !== b.name || a.slug !== b.slug || a.cc_model !== b.cc_model || a._deleted !== b._deleted) return true;
262	  }
263	  return false;
264	}
265	
266	/* ── Render helpers ──────────────────────────────────────── */
267	
268	/** Render the dirty indicator dot HTML for a field that has changed. */
269	function mrDirtyDot(isDirty) {
270	  return isDirty ? '<span class="mr-dirty-dot" title="Unsaved change"></span>' : '';
271	}
272	
273	/** Render a single read-only model row. */
274	function mrRenderRow(model) {
275	  var orig = mrOriginal ? mrOriginal.find(function (o) { return o.id === model.id; }) : null;
276	  var isNew      = !orig;
277	  var isDeleted  = !!model._deleted;
278	  var nameDirty  = orig && model.name     !== orig.name;
279	  var slugDirty  = orig && model.slug     !== orig.slug;
280	  var ccDirty    = orig && model.cc_model !== orig.cc_model;
281	
282	  var rowClass = 'mr-model-row' + (isDeleted ? ' mr-model-deleted' : '') + (isNew ? ' mr-model-new' : '');
283	
284	  return '<tr class="' + rowClass + '" data-id="' + escapeHtml(model.id) + '">' +
285	    '<td>' + mrDirtyDot(nameDirty || isNew) + escapeHtml(model.name) + '</td>' +
286	    '<td>' + mrDirtyDot(slugDirty || isNew) + '<code>' + escapeHtml(model.slug) + '</code></td>' +
287	    '<td>' +
288	      mrDirtyDot(ccDirty || isNew) +
289	      '<span title="Claude Code model override. Use \'inherit\' to defer to your Claude Code model setting.">' +
290	        escapeHtml(model.cc_model || 'inherit') +
291	      '</span>' +
292	    '</td>' +
293	    '<td class="mr-row-actions">' +
294	      (isDeleted
295	        ? '<button class="btn btn-sm btn-secondary mr-restore-btn" data-id="' + escapeHtml(model.id) + '">Restore</button>'
296	        : '<button class="btn btn-sm btn-secondary mr-edit-btn"    data-id="' + escapeHtml(model.id) + '">Edit</button>' +
297	          '<button class="btn btn-sm btn-danger  mr-delete-btn"   data-id="' + escapeHtml(model.id) + '">Delete</button>'
298	      ) +
299	    '</td>' +
300	  '</tr>';
301	}
302	
303	/** Render the edit row for the model currently being edited. */
304	function mrRenderEditRow(model) {
305	  var orig = mrOriginal ? mrOriginal.find(function (o) { return o.id === model.id; }) : null;
306	  var isNew      = !orig;
307	  var nameDirty  = orig && model.name     !== orig.name;
308	  var slugDirty  = orig && model.slug     !== orig.slug;
309	  var ccDirty    = orig && model.cc_model !== orig.cc_model;
310	  var slugError  = mrValidateSlug(model.slug);
311	
312	  return '<tr class="mr-model-row mr-edit-row" data-id="' + escapeHtml(model.id) + '">' +
313	    '<td>' +
314	      mrDirtyDot(nameDirty || isNew) +
315	      '<input type="text" class="form-control mr-field-name" value="' + escapeHtml(model.name) + '" placeholder="Model name" data-id="' + escapeHtml(model.id) + '">' +
316	    '</td>' +
317	    '<td>' +
318	      mrDirtyDot(slugDirty || isNew) +
