679	/** Send the working model list to PUT /api/models. */
680	function mrDoSave() {
681	  var saveBtn = document.getElementById('mr-save-btn');
682	  var msgEl   = document.getElementById('mr-msg');
683	  if (saveBtn) saveBtn.disabled = true;
684	  if (msgEl)   msgEl.innerHTML  = '<span style="color:var(--color-text-muted);font-size:13px;">Saving…</span>';
685	
686	  /* Strip the internal _deleted sentinel from entries that are being removed;
687	     the server expects a plain array where absent entries are deletions. */
688	  var payload = (mrModels || []).filter(function (m) { return !m._deleted; }).map(function (m) {
689	    return { id: m.id, name: m.name, slug: m.slug, cc_model: m.cc_model };
690	  });
691	
692	  API.saveModels(payload)
693	    .then(function (result) {
694	      /* Refresh state from server response */
695	      var saved = (result && result.models) ? result.models : payload;
696	      mrModels   = mrCloneModels(saved);
697	      mrOriginal = mrCloneModels(saved);
698	      mrEditingId = null;
699	      configDirty.modelRegistry = false;
700	      mrRefreshTab();
701	      /* Show success message */
702	      var msg2 = document.getElementById('mr-msg');
703	      if (msg2) msg2.innerHTML = '<span class="success-banner" style="display:inline-block;padding:4px 10px;">Saved successfully.</span>';
704	    })
705	    .catch(function (err) {
706	      var msg2 = document.getElementById('mr-msg');
707	      if (saveBtn) saveBtn.disabled = false;
708	      if (err && err.code === 'CONFLICT') {
709	        /* 409 — referenced model deletion */
710	        var conflictMsg =
711	          'Cannot delete one or more models because they are referenced by personas. ' +
712	          'Use the <strong>Replace Model</strong> feature on the Persona Models tab to reassign personas first, then retry.';
713	        if (msg2) msg2.innerHTML = '<p class="error-banner">' + conflictMsg + '</p>';
714	      } else {
715	        if (msg2) msg2.innerHTML = '<p class="error-banner">Save failed: ' + escapeHtml(err.message || String(err)) + '</p>';
716	      }
717	    });
718	}
